"""Inventory completed publication-ablation experiments; importing performs no archive/hash/JVM work."""

import importlib.util
import json
import os
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
PHASE = 'result-coordinate-evidence/publication-followup'
MANIFEST = PHASE + '/delivery/runtime-bundle-manifest.json'
sys.path.insert(0, str(ROOT / 'result-coordinate-evidence/materializer-followup'))
from comparison_runtime_io import (Inventory, file_hash, json_bytes, member_relative, path_under, portable,
                                   publish_no_replace, real_tree, recorded_relative, require, sha_bytes,
                                   signature, tree_digest)


def import_path(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.path.insert(0, str(path.parent))
    try:
        spec.loader.exec_module(module)
    finally:
        sys.path.remove(str(path.parent))
    return module


def source_argument(argv, schema):
    require(schema == 'query-harness', 'Unknown command schema')
    values = [argument.removeprefix('--source=') for argument in argv if argument.startswith('--source=')]
    require(len(values) == 1, 'Expected exactly one query source identity')
    return values[0]


def catalog(repo, inventory, protocol_relative, comparison_relative, diagnostic_suites):
    """Read only completed, frozen work. Call after the coordinator ends every timed run."""
    protocol_relative = portable(protocol_relative)
    comparison_relative = portable(comparison_relative)
    require(protocol_relative.startswith(PHASE + '/') and comparison_relative.startswith(PHASE + '/'),
            'Protocol and comparison must belong to this phase')
    require(diagnostic_suites and len(diagnostic_suites) == len(set(diagnostic_suites)),
            'Explicit unique diagnostic suite names are required')
    require(all(portable(name) == name and '/' not in name for name in diagnostic_suites), 'Invalid suite name')
    require(set(diagnostic_suites) == {'original512', 'overlay-all512', 'overlay-fanout-omit512',
            'overlay-shared-omit512', 'overlay-shared-all256', 'overlay-shared-omit256'},
            'This completed phase requires all six declared diagnostic suites')
    comparison = import_path('publication_delivery_comparison', repo / PHASE / 'benchmark/run-comparison.py')
    identity = comparison.identity
    original_cp, original_manifest = identity.original_identity()
    protocol, primary = comparison.validate_protocol(repo / protocol_relative)
    protocol_digest = inventory.add(protocol_relative)['sha256']
    require(inventory.read(comparison_relative + '/used-protocol.json') == inventory.read(protocol_relative),
            'Consumed comparison protocol differs')
    completed = inventory.json(comparison_relative + '/summary.json')
    require(completed['complete'] and completed['completedJvms'] == 36 and not completed['errors']
            and completed['rawQueryCount'] == 468 and completed['rawMeasuredQueryCount'] == 180
            and len(completed['densePairAudits']) == 12 and all(a['passed'] for a in completed['densePairAudits']),
            'This completed-comparison package requires all 36 fixed forks and their 468 valid queries')
    preservation = inventory.json(comparison_relative + '/post-run-preservation.json')
    require(preservation['identityFilesUnchanged'] and preservation['runtimeIdentityUnchanged'],
            'Comparison source/runtime preservation failed')
    artifacts, runtimes = {}, {}

    def relative(value):
        return recorded_relative(str(value), str(repo))

    def register(name, classpath, manifest, source_identity, descriptor=None):
        require(name not in runtimes, 'Duplicate runtime name: ' + name)
        require(classpath == os.pathsep.join(entry['path'] for entry in manifest), 'Classpath order differs: ' + name)
        entries = []
        for entry in manifest:
            rel = relative(entry['path'])
            if rel not in artifacts:
                if entry['kind'] == 'tree':
                    files = inventory.tree(rel)
                    require(len(files) == entry['files'] and tree_digest(files) == entry['sha256'],
                            'Changed artifact: ' + rel)
                else:
                    require(entry['kind'] == 'file' and rel.endswith('.jar'), 'Unexpected artifact type')
                    inventory.add(rel, entry['sha256'])
                artifacts[rel] = entry | {'path': 'rdf4j/' + rel, 'originalAbsolutePath': entry['path']}
            existing = artifacts[rel]
            require(existing['sha256'] == entry['sha256'] and existing['kind'] == entry['kind']
                    and existing.get('files') == entry.get('files'), 'Conflicting artifact identity')
            entries.append(existing['path'])
        runtimes[name] = {'originalClasspath': classpath, 'originalManifest': manifest, 'entries': entries,
                          'sourceIdentity': source_identity, 'descriptor': descriptor}

    def descriptor_runtime(name, path):
        rel = relative(path)
        descriptor = inventory.json(rel)
        for item in comparison.descriptor_inputs(descriptor).values():
            inventory.add(relative(item))
        cp = inventory.read(relative(descriptor['classpathFile'])).decode().strip()
        manifest = inventory.json(relative(descriptor['classpathManifestFile']))
        register(name, cp, manifest, descriptor['sourceIdentity'], descriptor)
        runtimes[name]['descriptorPath'] = 'rdf4j/' + rel
        return manifest

    register('original-base', original_cp, original_manifest, identity.ORIGINAL_SOURCE)
    common = descriptor_runtime('common-harness', protocol['commonHarnessDescriptorFile'])
    timing = descriptor_runtime('publication-timing', protocol['runtimeDescriptorFile'])
    require(len(common) == 128 and common[1:] == original_manifest
            and len(timing) == 129 and timing[1:] == common and timing == primary['manifest'],
            'Original/common/publication composition differs from the timed protocol')
    require(primary['descriptor']['diagnosticOnly'] is False and primary['descriptor']['noProductionPromotion'],
            'Unexpected production selection or diagnostic timing runtime')
    timing_folder = Path(protocol['runtimeDescriptorFile']).parent
    emitted = inventory.tree(relative(timing_folder / 'emitted-classes'))
    require(emitted == inventory.json(relative(primary['descriptor']['emittedClassFilesFile'])) and len(emitted) == 4,
            'Raw materializer javac outputs differ')
    raw_outputs = {'publication-timing': {'path': 'rdf4j/' + relative(timing_folder / 'emitted-classes'), 'files': emitted}}

    diagnostic_commands = []
    suites = []
    diagnostic_modules = {}
    diagnostic_identity = import_path('publication_delivery_diagnostic_identity',
        repo / 'result-coordinate-evidence/compact-page-followup/runtime_identity.py')
    for name in diagnostic_suites:
        suite_rel = PHASE + '/diagnostic/suites/' + name
        pinned_plan = inventory.json(suite_rel + '/protocol.json')
        allowed_drivers = [repo / PHASE / 'diagnostic' / filename
                           for filename in ('run_diagnostic.py', 'run_diagnostic_v2.py')]
        drivers = [path for path in allowed_drivers if str(path) in pinned_plan['sources']]
        require(len(drivers) == 1, 'Diagnostic suite must bind exactly one preserved driver')
        driver = drivers[0]
        for path, digest in pinned_plan['sources'].items():
            inventory.add(relative(path), digest)
        if driver not in diagnostic_modules:
            # The preserved diagnostic driver imports the compact study by filename; bind its own identity helper.
            previous_identity = sys.modules.get('runtime_identity')
            try:
                sys.modules['runtime_identity'] = diagnostic_identity
                diagnostic_modules[driver] = import_path('publication_delivery_' + driver.stem, driver)
            finally:
                if previous_identity is None:
                    sys.modules.pop('runtime_identity', None)
                else:
                    sys.modules['runtime_identity'] = previous_identity
        diagnostic = diagnostic_modules[driver]
        folder, plan, runtime, cp = diagnostic.load_plan(name)
        require(relative(folder) == suite_rel and plan == pinned_plan, 'Diagnostic protocol changed during inventory')
        plan_hash = inventory.add(suite_rel + '/protocol.json')['sha256']
        analysis = inventory.json(suite_rel + '/analysis.json')
        require(analysis['valid'] and analysis['performanceInference'] is False
                and analysis['protocolSha256'] == plan_hash and set(analysis['fixtures']) == set(plan['fixtures']),
                'Diagnostic suite did not qualify: ' + name)
        runtime_rel = relative(plan['runtime'])
        inventory.add(runtime_rel, plan['runtimeSha256'])
        inventory.add(relative(runtime['baseRuntimeDescriptor']), runtime['baseRuntimeDescriptorSha256'])
        inventory.add(relative(runtime['sourceGenerationFile']), runtime['sourceGenerationSha256'])
        inventory.add(relative(runtime['classpathFile']), runtime['classpathFileSha256'])
        inventory.add(relative(runtime['classpathManifestFile']), runtime['classpathManifestSha256'])
        runtime_name = 'publication-diagnostic' if runtime['maskGuardPresent'] else 'original-diagnostic'
        expected_base = timing if runtime['maskGuardPresent'] else common
        require(runtime['manifest'][1:] == expected_base and runtime['baseManifest'] == expected_base,
                'Diagnostic changed its selected common/base runtime')
        if runtime_name not in runtimes:
            register(runtime_name, cp, runtime['manifest'], runtime['sourceIdentity'], runtime)
            runtimes[runtime_name]['descriptorPath'] = 'rdf4j/' + runtime_rel
            raw_rel = relative(Path(plan['runtime']).parent / 'compiled-output')
            raw = inventory.tree(raw_rel)
            require(raw == runtime['rawJavacOutput'] and len(raw) == 5, 'Raw diagnostic javac output differs')
            raw_outputs[runtime_name] = {'path': 'rdf4j/' + raw_rel, 'files': raw}
        else:
            require(runtimes[runtime_name]['originalClasspath'] == cp
                    and runtimes[runtime_name]['descriptor'] == runtime, 'A diagnostic composition changed across suites')
        for fixture in plan['fixtures']:
            receipt = analysis['fixtures'][fixture]
            fixture_analysis = inventory.json(relative(receipt['analysis']), receipt['analysisSha256'])
            require(receipt['valid'] and fixture_analysis['valid'], 'Diagnostic fixture failed')
            run_rel = suite_rel + '/runs/' + fixture
            command = inventory.json(run_rel + '/command.json')
            require(command['protocolSha256'] == plan_hash and command['runtimeSha256'] == plan['runtimeSha256'],
                    'Diagnostic command protocol/runtime differs')
            diagnostic_commands.append(('page-diagnostic', 'query-harness', run_rel + '/command.json',
                                        runtime_name, fixture, plan['name']))
        suites.append({'name': name, 'protocol': 'rdf4j/' + suite_rel + '/protocol.json',
                       'protocolSha256': plan_hash, 'runtime': runtime_name,
                       'driver': 'rdf4j/' + relative(driver),
                       'fixtures': list(plan['fixtures']), 'mask': plan['mask'],
                       'queryLimitBytes': plan['queryLimitBytes']})
    require(len(runtimes) == 5 and len(artifacts) == 131, 'Unexpected runtime/unique-artifact count')
    require(len(diagnostic_commands) == 8, 'Expected eight diagnostic JVM commands across the six suites')

    command_files = []
    for round_index, order in enumerate(protocol['balancedOrders']):
        for fixture_position, fixture in enumerate(protocol['fixtureOrdersByRound'][round_index]):
            for position, arm in enumerate(order):
                folder = f'round-{round_index:02d}-{fixture_position:02d}-{fixture}-{position:02d}-{arm}'
                command_files.append(('primary', 'query-harness', comparison_relative + '/' + folder + '/command.json',
                                      'publication-timing', fixture, arm))
    require(len(command_files) == 36, 'Incomplete fixed primary command inventory')
    command_files += diagnostic_commands
    commands, intervals = [], []
    for index, (purpose, schema, rel, expected_runtime, fixture, arm) in enumerate(command_files):
        record = inventory.json(rel)
        argv = record['argv']
        require(argv.count('-cp') == 1 and record['cwd'] == str(repo), 'Unexpected command classpath/cwd')
        cp = argv[argv.index('-cp') + 1]
        matches = [name for name, runtime in runtimes.items() if runtime['originalClasspath'] == cp]
        require(matches == [expected_runtime], 'Command must bind exactly its expected frozen runtime')
        runtime_name = matches[0]
        require(source_argument(argv, schema) == runtimes[runtime_name]['sourceIdentity'], 'Command source differs')
        folder = rel.removesuffix('command.json')
        raw_path = folder + 'samples.jsonl'
        records = [json.loads(line) for line in inventory.read(raw_path).splitlines() if line.strip()]
        metadata, samples = records[0], records[1:]
        require(metadata['type'] == 'metadata' and metadata['source'] == runtimes[runtime_name]['sourceIdentity']
                and metadata['arm'] == arm, 'Raw metadata source/arm differs')
        require(argv[argv.index('-cp') + 2] == protocol['fixtures'][fixture]['launcher'], 'Unexpected query entry point')
        require(len(samples) == (13 if purpose == 'primary' else 4)
                and all(s['valid'] and s['complete'] and s['ledgerBeforeBytes'] == s['ledgerAfterBytes'] == 0
                        and s['ledgerReleased'] for s in samples), 'Raw queries are incomplete or invalid')
        process = inventory.json(folder + 'process-result.json')
        require(process['exitCode'] == 0 and not process.get('failure'), 'A recorded process failed')
        started, finished = record['startedEpochNs'], process['finishedEpochNs']
        require(started <= finished and process.get('startedEpochNs', started) == started, 'Invalid process interval')
        if purpose == 'primary':
            validation = inventory.json(folder + 'validation.json')
            require(validation['resultValidity'] == 'passed' and validation['targetQualified']
                    and validation['queryCount'] == 13 and validation['measuredQueryCount'] == 5,
                    'A primary fork did not qualify')
        intervals.append((started, finished, rel))
        commands.append({'label': f'{index:02d}-' + rel.split('/')[-2], 'purpose': purpose,
                         'schema': schema, 'runtime': runtime_name, 'recordPath': 'rdf4j/' + rel,
                         'originalArgv': argv, 'originalCwd': record['cwd'],
                         'originalResultPath': 'rdf4j/' + raw_path, 'expectedMetadata': metadata,
                         'originalProcessInterval': {'startedEpochNs': started, 'finishedEpochNs': finished},
                         'timeoutSeconds': 300})
    intervals.sort()
    require(all(left[1] <= right[0] for left, right in zip(intervals, intervals[1:])),
            'Recorded diagnostic/timed JVM intervals overlap')
    return {'artifacts': list(artifacts.values()), 'runtimes': runtimes, 'commands': commands,
            'primaryProtocolSha256': protocol_digest, 'primaryProtocol': protocol_relative,
            'primaryComparison': comparison_relative, 'diagnosticSuites': suites,
            'rawCompilerOutputs': raw_outputs, 'recordedJvmIntervalsNonOverlapping': True}


def validate_extracted(repo, expected_manifest=None):
    manifest_path = path_under(repo, MANIFEST)
    data = manifest_path.read_bytes()
    require(expected_manifest is None or sha_bytes(data) == expected_manifest, 'Bundle manifest checksum differs')
    manifest = json.loads(data)
    require(manifest['format'] == 1 and manifest['archivePrefix'] == 'rdf4j'
            and manifest['selfContainedRuntime'] and not manifest['jdkIncluded'], 'Unexpected bundle manifest')
    inventory = Inventory(repo)
    for record in manifest['files']:
        actual = inventory.add(member_relative(record['path']), record['sha256'])
        require(actual == record, 'Extracted file metadata differs: ' + record['path'])
    artifacts = {entry['path']: entry for entry in manifest['runtimeArtifacts']}
    for artifact in artifacts.values():
        relative = member_relative(artifact['path'])
        if artifact['kind'] == 'tree':
            files = inventory.tree(relative)
            require(len(files) == artifact['files'] and tree_digest(files) == artifact['sha256'], 'Extracted tree differs')
        else:
            inventory.add(relative, artifact['sha256'])
    for runtime in manifest['runtimes'].values():
        require(runtime['originalClasspath'] == os.pathsep.join(entry['path'] for entry in runtime['originalManifest']),
                'Recorded classpath order differs')
        require(len(runtime['entries']) == len(runtime['originalManifest']), 'Runtime entry count differs')
        for path, original in zip(runtime['entries'], runtime['originalManifest']):
            require(path in artifacts, 'Runtime references an absent artifact')
            artifact = artifacts[path]
            require(artifact['originalAbsolutePath'] == original['path'] and artifact['kind'] == original['kind']
                    and artifact['sha256'] == original['sha256'] and artifact.get('files') == original.get('files'),
                    'Runtime artifact mapping differs')
    for command in manifest['commands']:
        raw = inventory.json(member_relative(command['recordPath']))
        require(raw['argv'] == command['originalArgv'] and raw['cwd'] == command['originalCwd'], 'Raw command differs')
        runtime = manifest['runtimes'][command['runtime']]
        argv = command['originalArgv']
        require(argv.count('-cp') == 1 and argv[argv.index('-cp') + 1] == runtime['originalClasspath']
                and source_argument(argv, command['schema']) == runtime['sourceIdentity'], 'Command/runtime differs')
    inventory.assert_stable()
    return manifest, sha_bytes(data)
